  /* शुभारंभ का अर्थ — फिर से शुरुआतWhy we started again */
  "1h7w2y": "<span class=\"deva\">शुभारंभ का अर्थ — फिर से शुरुआत</span>हमने फिर से शुरुआत क्यों की",
  /* Shubharambh means an auspicious beginning. We chose the name because we wanted to start ag */
  "13nfr2r": "शुभारंभ का अर्थ है शुभ आरंभ। हमने यह नाम इसलिए चुना क्योंकि हम उन चीज़ों के साथ फिर से शुरुआत करना चाहते थे जिन्हें भारत कभी अच्छी तरह जानता था।",
  /* How it began */
